import importlib, json, os, platform, sys, uuid
BOOT = str(uuid.uuid4())
def handler(event, context):
    modules = {}
    for name in ('overlap', 'only_a', 'only_b', 'extra_c', 'extra_d', 'extra_e', 'extra_f'):
        try:
            module = importlib.import_module(name)
            modules[name] = {'value': module.VALUE, 'file': module.__file__}
        except ModuleNotFoundError as error:
            modules[name] = {'missing': error.name}
    try:
        shared = open('/opt/shared.txt').read()
    except FileNotFoundError:
        shared = None
    return {'modules': modules, 'shared': shared, 'boot': BOOT, 'environment': os.getenv('PROBE'), 'function_version': context.function_version, 'python': platform.python_version(), 'machine': platform.machine(), 'sys_path': sys.path}
